import{_ as i,l as o,o as e,c as s,v as t,p as n,x as r,d as p,i as A,S as d}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"LACP","description":"","frontmatter":{"title":"LACP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lacp.md","filePath":"cs/lacp.md","lastUpdated":1789023840000}'),c={name:"cs/lacp.md"};function P(h,a,E,C,_,L){const l=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="lacp" tabindex="-1">LACP <a class="header-anchor" href="#lacp" aria-label="Permalink to &quot;LACP&quot;">​</a></h1><div class="epigraph"><p>多条物理链路绑成一条逻辑链路，既要防环又要分摊流量；LACP 用协议确认对端也同意捆绑，避免单边聚合把环藏起来。</p><footer>—— 据 IEEE 802.1AX（原 802.3ad）Link Aggregation 整理</footer></div><p><a href="/cs/jumbo-mtu">上一课</a>要求路径 MTU 一致。多口并联若只在一边静态捆绑，另一边仍当独立口，<a href="/cs/spanning-tree">生成树</a> 与泛洪会错。缺口是 <strong>LACP</strong>：两端交换 LACPDU，形成聚合组，MAC 学习看到一个逻辑口。本课不把 LLDP TLV 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>升速可以换更快 PHY，也可以 4×10G 当 40G 用。静态捆绑：配错则成环或黑洞。LACP：Actor/Partner 系统 ID、密钥、端口优先级，只有匹配的口进入 Collecting/Distributing。流量按哈希分到成员（后课 ECMP 是三层同类问题）。一条成员故障，逻辑链路降速不断。</p><p>不要把 PHY 多 lane（100GBASE-SR4）当成 LACP：lane 在模块内 deskew，LACP 在 MAC 之间。</p><p><span class="marginnote">802.1AX 把聚合从 802.3 抽出。模式 active/passive 决定谁先发 PDU。本课不把每家芯片的哈希多项式背完。</span></p><h3 id="捆绑确认对端" tabindex="-1">捆绑确认对端 <a class="header-anchor" href="#捆绑确认对端" aria-label="Permalink to &quot;捆绑确认对端&quot;">​</a></h3><p>静态单边聚合会藏环。逻辑口对 STP 是一条边；哈希保序不保大象流均衡。PHY 多 lane 不要叫 LACP。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选举：系统优先级 → 口优先级 → 选活动成员。画：物理口 → LAG 逻辑口 → 桥接表。哈希键通常含 MAC/IP/端口，保证同流同成员，避免乱序。与 STP：LAG 是一条边，不会在成员之间形成二层环。</p>',11)),(e(),n(d,null,{default:r(()=>[A(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20P1%5B%22%E7%89%A9%E7%90%86%E5%8F%A3%22%5D%20--%3E%20LAG%5B%22LACP%20%E8%81%9A%E5%90%88%E7%BB%84%22%5D%0A%20%20P2%5B%22%E7%89%A9%E7%90%86%E5%8F%A3%22%5D%20--%3E%20LAG%0A%20%20LAG%20--%3E%20FWD%5B%22%E4%BD%9C%E4%B8%BA%E4%B8%80%E6%9D%A1%E6%A1%A5%E6%8E%A5%E8%BE%B9%22%5D%0A%20%20LAG%20--%3E%20HASH%5B%22%E6%B5%81%E5%93%88%E5%B8%8C%E5%88%B0%E6%88%90%E5%91%98%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>自协商仍按成员口独立完成；速率不一致通常不允许入组。PAUSE 可按成员，逻辑上仍应避免不对称暂停。巨帧必须全体成员一致。主干 CSMA 课的「交换」在此变成「交换 + 捆绑」。</p><p>控制面：LACPDU 走慢协议组播，不被数据哈希打乱。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 MLAG/vPC 跨机箱聚合的全部一致性协议。LLDP 是下一课。后课默认：捆绑成功当一条二层边；哈希保序不保完美均衡。</p><p>极化（elephant 流打满一条成员）是哈希的边界，要用更细的键或后课 ECMP 对照。</p><p>上一课留下的缺口在本课收口；「LACP」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/lldp">LLDP</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LACP 确认对端后才转发，避免单边聚合。</li><li>逻辑口对 STP 与 MAC 表是一条边。</li><li>同流同成员，防乱序。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：IEEE 802.1AX。</li></ul>',10))])}const f=i(c,[["render",P]]);export{u as __pageData,f as default};
